#ifndef CSM_GITHUB_H
#define CSM_GITHUB_H

#include <stddef.h>

#include "inventory.h"
#include "move.h"

/* A path in githubRepoPaths of .claude.json, with the state of 4.5. */
struct github_entry {
	char *repo;
	char *path;
	enum dir_state state;
};

int github_scan(const char *config_file, struct github_entry **entries,
    size_t *count);
size_t github_dead(const struct github_entry *entries, size_t count);
void github_entries_free(struct github_entry *entries, size_t count);
int github_has_repo(const struct github_entry *entries, size_t count,
    const char *repo);
size_t github_prune(struct move_ctx *ctx, char *const *repos, size_t count);
char **fix_candidates(const char *old_path, const struct inventory *inv,
    const char *config_file, size_t *count);
void fix_candidates_free(char **candidates, size_t count);

#endif
